#!/bin/bash
#
# Makes src/musashi again (`make musashi`): Musashi (MIT licence, pinned)
# with the instruction hook and separate reads on and no PMMU, its opcode
# handlers generated by m68kmake, then slimmed for the Game & Watch by
# tools/slim_musashi.py (constant two-level decode table instead of 576 KB
# of tables built at start-up, fixed cycles, no FPU/PMMU opcodes). The
# homebrew, the PC version and make_crs all use these files.
#
# Needs gcc, git and python3.
#
# usage: tools/update_musashi.sh

set -euo pipefail

root=$(cd "$(dirname "$0")/.." && pwd)
work=$root/build/musashi
src=$root/src/musashi
mkdir -p "$work"

if [ ! -d "$work/Musashi" ]; then
	git clone -q https://github.com/kstenerud/Musashi.git "$work/Musashi"
	git -C "$work/Musashi" checkout -q 313ebf1bd9f4d0d93341eb5ce21fd8a119e9dbdd
fi

gen=$work/gen
rm -rf "$gen"
mkdir -p "$gen"
cp "$work"/Musashi/{m68kcpu.c,m68kdasm.c,m68k.h,m68kcpu.h,m68kfpu.c,m68kmmu.h,m68k_in.c,m68kmake.c} "$gen/"
cp -r "$work/Musashi/softfloat" "$gen/"
sed -e 's/#define M68K_INSTRUCTION_HOOK       M68K_OPT_OFF/#define M68K_INSTRUCTION_HOOK       M68K_OPT_ON/' \
	-e 's/#define M68K_SEPARATE_READS         M68K_OPT_OFF/#define M68K_SEPARATE_READS         M68K_OPT_ON/' \
	-e 's/#define M68K_EMULATE_PMMU           M68K_OPT_ON/#define M68K_EMULATE_PMMU           M68K_OPT_OFF/' \
	"$work/Musashi/m68kconf.h" > "$gen/m68kconf.h"
grep -q "M68K_INSTRUCTION_HOOK       M68K_OPT_ON" "$gen/m68kconf.h"
grep -q "M68K_SEPARATE_READS         M68K_OPT_ON" "$gen/m68kconf.h"
grep -q "M68K_EMULATE_PMMU           M68K_OPT_OFF" "$gen/m68kconf.h"
(cd "$gen" && gcc -O2 -o m68kmake m68kmake.c && ./m68kmake . m68k_in.c > /dev/null)
python3 "$root/tools/slim_musashi.py" "$gen"

rm -rf "$src"
mkdir -p "$src/softfloat"
for f in m68k.h m68kconf.h m68kcpu.c m68kcpu.h m68kfpu.c m68kmmu.h m68kops.c m68kops.h; do
	cp "$gen/$f" "$src/"
done
cp "$gen"/softfloat/* "$src/softfloat/"
cp "$work/Musashi/readme.txt" "$src/README-Musashi.txt"
echo "src/musashi made again"
